// Mobile signup uses the existing bundled fonts before its first visible frame.
// The bytes below are copied unchanged from the named assets in ../fonts/.
if (window.matchMedia('(max-width: 768px)').matches) {
  const latinRange = 'U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD';
  const fonts = [{"family":"Sarabun","weights":["200","300"],"sourceFile":"DtVmJx26TKEr37c9YNpoilss6yLUrwA.woff2","data":""},{"family":"Sarabun","weights":["400"],"sourceFile":"DtVjJx26TKEr37c9aBVJn3YO5gg.woff2","data":""},{"family":"Sarabun","weights":["600"],"sourceFile":"DtVmJx26TKEr37c9YMptilss6yLUrwA.woff2","data":""},{"family":"Cormorant Garamond","weights":["300","400","600"],"sourceFile":"co3bmX5slCNuHLi8bLeY9MK7whWMhyjYqXtKky2F7g.woff2","data":""}];
  for (const font of fonts) {
    const bytes = Uint8Array.from(atob(font.data), character => character.charCodeAt(0));
    for (const weight of font.weights) {
      document.fonts.add(new FontFace(font.family, bytes, { weight, unicodeRange: latinRange }));
    }
  }
  const mobileLayout = document.createElement('style');
  mobileLayout.textContent = `
    @media (max-width: 768px) {
      .signup-page:not(.signup-application-step) #stepOnePanel > :is(#nextStepBtn, #msg, .extra-links) { top: 0 !important; }
      .signup-page:not(.signup-application-step):not(.signup-received) .signup-stage { bottom: 48px; }
      .signup-page.auth-entry:not(.signup-application-step):not(.signup-received) .overlay { height: auto !important; }
      .signup-page.auth-entry:not(.signup-application-step):not(.signup-received) .left-panel { height: auto; padding-bottom: 30px; }
    }
    @media (max-width: 768px) and (max-height: 700px) {
      .signup-page.auth-entry:not(.signup-application-step):not(.signup-received) .left-panel { padding-bottom: 20px; }
    }
  `;
  document.head.appendChild(mobileLayout);
}
